// Package utf8fold compares names the way the Linux utf8 module does for the
// encoding utf8-12.1.0, the one ext4 and F2FS casefold directories use.
//
// The comparison form of a name (Key) is NFD(casefold(NFD(x))) with the default-ignorable code points
// removed, computed per code point from tables generated from the committed Unicode 12.1.0 files
// (tables_gen.go, regenerated byte for byte by TestGenerateTables). Hangul syllables are decomposed
// arithmetically. Combining marks are put in canonical order after the whole name is expanded.
//
// What the kernel does with a name that is not valid UTF-8 was MEASURED in a QEMU guest
// (tools/fixtures/README.md, "Casefold lookup oracle"; 611 rows of kernel-vectors.json.gz, ext4 and F2FS
// agreeing on every one). Only the shapes a committed vector row shows are decided (decidedShapes,
// TestEveryDecidedShapeIsShownByAVector); each is reproduced exactly, no more:
//
//   - a stray continuation byte (0x80-0xBF where a character should start) that comes after at least one
//     byte of the name is an ordinary character that folds to itself and is never dropped; the text around
//     it is folded and normalized, and marks after it are ordered among themselves (FormUnicode);
//   - one or two stray bytes at the start of a name, followed by nothing, by ASCII, or (for one) by text
//     with a non-ASCII character and no later stray byte, make the whole name opaque; so does an invalid
//     tail at the END of a name that has plain text (stray bytes allowed) before it, when the tail is a lone
//     lead byte 0xC0-0xFF, a lead byte and one stray byte, ED A0 80, F4 90 80 80, F8 88 80 80 80 or FE FE:
//     an opaque name is compared byte for byte, no folding, no normalization (FormOpaque);
//   - U+FFFE, U+FFFF and U+10FFFF are ordinary characters.
//
// A shape is the whole combination (the text before an invalid tail, where the stray bytes sit, and the tail
// form), not its parts: a prefix and a tail that are each shown but never together are undecided. Every other
// shape is FormUndecided: the empty name, a name over MaxName, an invalid byte followed by text
// or by a valid character, any other tail, a leading stray byte with a later stray byte or an ignorable
// character, an ignorable character before an invalid tail, and a stray byte ANYWHERE in a name that also has
// an ignorable character. Equal reports Unknown for them and Key refuses. A caller must report that it cannot
// decide; it must never treat the answer as "different" or fold the name by a guess. The one exception is
// Equal's measured pair, an opaque name against itself plus a lowercase 'z'.
//
// A code point assigned after Unicode 12.1 has no case mapping (measured); it still takes part in mark
// ordering. Runs of up to 40 combining marks are ordered completely (measured); the stream-safe limit of
// the kernel is not modelled because no vector shows one.
package utf8fold

import (
	"bytes"
	"slices"
	"unicode/utf8"
)

// Version is the Unicode version of the tables.
const Version = "12.1.0"

// EncodingUTF8v121 is s_encoding of ext4 and F2FS for utf8-12.1.0 (no underscore: the lint's naming rule).
const EncodingUTF8v121 = 1

// MaxName is the longest name Key accepts (a filesystem name is at most 255 bytes).
const MaxName = 255

// Supported reports whether encoding is one this package implements.
func Supported(encoding uint16) bool { return encoding == EncodingUTF8v121 }

type runeRange struct{ lo, hi rune }

type cccRange struct {
	lo, hi rune
	class  uint8
}

// mapEntry names a run of data (off, n) for code point r.
type mapEntry struct {
	r   rune
	off uint32
	n   uint8
}

const (
	hangulS     = 0xAC00
	hangulL     = 0x1100
	hangulV     = 0x1161
	hangulT     = 0x11A7
	hangulTCnt  = 28
	hangulNCnt  = 21 * hangulTCnt
	hangulCount = 19 * hangulNCnt
)

// strayBase marks a stray continuation byte b inside a rune buffer as strayBase+b (above every code point).
const strayBase = 0x110000

// appendHangul appends the jamo of the syllable r.
func appendHangul(dst []rune, r rune) []rune {
	s := r - hangulS
	dst = append(dst, hangulL+s/hangulNCnt, hangulV+(s%hangulNCnt)/hangulTCnt)
	if t := s % hangulTCnt; t != 0 {
		dst = append(dst, hangulT+t)
	}
	return dst
}

// Form is how the kernel compares a name.
type Form int

const (
	// FormUnicode: the name is text (stray continuation bytes after the first byte included); Key is its
	// comparison form.
	FormUnicode Form = iota
	// FormOpaque: the kernel compares the name byte for byte (measured).
	FormOpaque
	// FormUndecided: an invalid shape no measurement covers, or a name longer than MaxName.
	FormUndecided
)

func (f Form) String() string {
	switch f {
	case FormUnicode:
		return "unicode"
	case FormOpaque:
		return "opaque"
	default:
		return "undecided"
	}
}

// decidedShapes is the exact set of composite shape labels Classify decides: every label some committed
// kernel vector name has, and no other (TestEveryDecidedShapeIsShownByAVector checks both directions, so a
// combination of a shown prefix and a shown tail that no vector shows together stays undecided: "measured,
// no more"). A label is one of
//
//	u:text                 valid UTF-8 only (any mix of ASCII, wide and default-ignorable characters)
//	u:s:<signature>        valid text with stray continuation bytes after the first byte
//	o:lead:<signature>     opaque: stray bytes first, then (more) text and stray bytes
//	o:t:<prefix>|<tail>    opaque: text (stray bytes allowed) then an invalid tail at the end
//
// where a signature lists the characters in order as a (ASCII), w (non-ASCII), i (default-ignorable) and s (a
// stray byte), a run of a, w or i collapsed to one letter, and <tail> names the invalid tail. The ignorable
// letter makes "a stray byte in a name that also has an ignorable" and "an ignorable before an invalid
// tail" unshown, hence undecided.
var decidedShapes = []string{
	"o:lead:s",
	"o:lead:sa",
	"o:lead:saw",
	"o:lead:ss",
	"o:lead:ssa",
	"o:lead:sw",
	"o:t:as|ed-a0-80",
	"o:t:as|f4-90-80-80",
	"o:t:as|lead",
	"o:t:as|lead+stray",
	"o:t:aw|ed-a0-80",
	"o:t:aw|f4-90-80-80",
	"o:t:aw|f8-88-80-80-80",
	"o:t:aw|fe-fe",
	"o:t:aw|lead",
	"o:t:aw|lead+stray",
	"o:t:a|ed-a0-80",
	"o:t:a|f4-90-80-80",
	"o:t:a|f8-88-80-80-80",
	"o:t:a|fe-fe",
	"o:t:a|lead",
	"o:t:a|lead+stray",
	"o:t:ws|lead",
	"o:t:w|ed-a0-80",
	"o:t:w|f4-90-80-80",
	"o:t:w|f8-88-80-80-80",
	"o:t:w|fe-fe",
	"o:t:w|lead",
	"o:t:w|lead+stray",
	"u:s:as",
	"u:s:asa",
	"u:s:asasa",
	"u:s:asasasa",
	"u:s:asaw",
	"u:s:ass",
	"u:s:asw",
	"u:s:aswas",
	"u:s:asws",
	"u:s:aws",
	"u:s:ws",
	"u:text",
}

var decidedSet = func() map[string]struct{} {
	m := make(map[string]struct{}, len(decidedShapes))
	for _, s := range decidedShapes {
		m[s] = struct{}{}
	}
	return m
}()

func isStray(b byte) bool { return b >= 0x80 && b <= 0xBF }

// tailKind names the invalid tail, or "" when the tail is not one of the shapes a vector shows.
func tailKind(t []byte) string {
	switch {
	case len(t) == 1 && t[0] >= 0xC0:
		return "lead"
	case len(t) == 2 && t[0] >= 0xC0 && isStray(t[1]):
		return "lead+stray"
	case bytes.Equal(t, []byte{0xED, 0xA0, 0x80}):
		return "ed-a0-80"
	case bytes.Equal(t, []byte{0xF4, 0x90, 0x80, 0x80}):
		return "f4-90-80-80"
	case bytes.Equal(t, []byte{0xF8, 0x88, 0x80, 0x80, 0x80}):
		return "f8-88-80-80-80"
	case bytes.Equal(t, []byte{0xFE, 0xFE}):
		return "fe-fe"
	}
	return ""
}

// appendSig appends the signature of part (valid text with stray bytes; the first non-stray invalid byte, if
// any, is not in part).
func appendSig(b, part []byte) []byte {
	var last byte
	for i := 0; i < len(part); {
		r, size := utf8.DecodeRune(part[i:])
		var c byte
		switch {
		case r == utf8.RuneError && size == 1:
			c = 's'
		case isIgnorable(r):
			c = 'i'
		case r < 0x80:
			c = 'a'
		default:
			c = 'w'
		}
		i += size
		if c != 's' && c == last {
			continue
		}
		b = append(b, c)
		last = c
	}
	return b
}

// labelOf computes the composite shape label of name, and the form that label would give. ok is false when
// the name has no shape at all (empty, over MaxName, or an invalid byte not at the end in a listed tail
// form). A label may be computed and still be undecided: only labels in decidedShapes are decided.
func labelOf(name []byte, buf []byte) (label []byte, form Form, ok bool) {
	if len(name) == 0 || len(name) > MaxName {
		return nil, FormUndecided, false
	}
	strays := 0
	tail := -1
	for i := 0; i < len(name); {
		r, size := utf8.DecodeRune(name[i:])
		if r == utf8.RuneError && size == 1 {
			if isStray(name[i]) {
				strays++
				i++
				continue
			}
			tail = i
			break
		}
		i += size
	}
	b := buf[:0]
	switch {
	case tail < 0 && strays == 0:
		return append(b, "u:text"...), FormUnicode, true
	case tail < 0 && isStray(name[0]):
		b = append(b, "o:lead:"...)
		return appendSig(b, name), FormOpaque, true
	case tail < 0:
		b = append(b, "u:s:"...)
		return appendSig(b, name), FormUnicode, true
	case tail == 0:
		return nil, FormUndecided, false
	}
	tk := tailKind(name[tail:])
	if tk == "" {
		return nil, FormUndecided, false
	}
	b = append(b, "o:t:"...)
	b = appendSig(b, name[:tail])
	b = append(b, '|')
	return append(b, tk...), FormOpaque, true
}

// Classify decides how the kernel compares name; see the package comment. Only shapes that a committed
// kernel vector shows are decided; every other shape is FormUndecided.
func Classify(name []byte) Form {
	var buf [320]byte
	label, form, ok := labelOf(name, buf[:0])
	if !ok {
		return FormUndecided
	}
	if _, shown := decidedSet[string(label)]; !shown {
		return FormUndecided
	}
	return form
}

// Key appends the comparison form of name to dst. ok is false, and dst is returned unchanged, unless name
// is FormUnicode; the caller then compares bytes (FormOpaque) or cannot decide (FormUndecided).
func Key(dst, name []byte) (key []byte, ok bool) {
	if Classify(name) != FormUnicode {
		return dst, false
	}
	// at most len(name) code points, each adding at most maxKeyRunesPerRune items: the bound comes from the
	// name that exists, never from anything it declares
	dst, _ = fillKey(dst, make([]item, 0, len(name)*maxKeyRunesPerRune), name)
	return dst, true
}

// fillKey appends the key of the FormUnicode name to dst, using items (reset first) as scratch; it returns
// both so a caller can reuse the buffers.
func fillKey(dst []byte, items []item, name []byte) ([]byte, []item) {
	items = items[:0]
	for i := 0; i < len(name); {
		r, size := utf8.DecodeRune(name[i:])
		if r == utf8.RuneError && size == 1 { // a stray continuation byte (Classify checked the rest)
			items = append(items, item{strayBase + rune(name[i]), 0})
			i++
			continue
		}
		i += size
		if isIgnorable(r) {
			continue
		}
		items = appendFolded(items, r)
	}
	reorder(items)
	dst = slices.Grow(dst, len(items)*utf8.UTFMax)
	for _, it := range items {
		if it.r >= strayBase {
			dst = append(dst, byte(it.r-strayBase))
		} else {
			dst = utf8.AppendRune(dst, it.r)
		}
	}
	return dst, items
}

// Verdict is the answer to "are these two names the same name": a tri-state, so that "cannot decide" is
// never mistaken for "different". The zero value is Unknown.
type Verdict int

const (
	// Unknown: the kernel's answer is not known (an empty name, a name over MaxName, a shape no vector shows).
	Unknown Verdict = iota
	// Same: the kernel resolves one name to the other.
	Same
	// Different: it does not.
	Different
)

func (v Verdict) String() string {
	switch v {
	case Same:
		return "same"
	case Different:
		return "different"
	default:
		return "unknown"
	}
}

// Equal compares two names the way the kernel does. An empty name (a filesystem name is never empty) is
// Unknown. Identical bytes are Same under any rule. An opaque name is Different from every other name, a
// text name compares by Key, and a name of any other shape is Unknown. A caller must treat Unknown as
// "cannot decide": never as Different, never as "not found".
//
// One pair of otherwise-Unknown names is decided because it was measured: an opaque name against the same
// name with one more byte, a lowercase 'z' (the negative controls of the invalid rows of the vectors), is
// Different. The kernel meets the invalid byte in the common prefix of both, falls back to comparing bytes,
// and the lengths differ. No other extension (an upper-case Z, another letter, two bytes) is assumed.
func Equal(a, b []byte) Verdict { return NewQuery(a).Compare(b) }

// Query compares one name (the query) with many, as a directory scan does, without allocating for each
// comparison: the query's form and key are computed once and the scratch buffers are reused. Compare(x)
// returns exactly Equal(query, x). A Query is not safe for concurrent use.
type Query struct {
	name  []byte
	form  Form
	key   []byte
	items []item
	tmp   []byte
}

// NewQuery prepares name for comparisons.
func NewQuery(name []byte) *Query {
	q := &Query{name: slices.Clone(name), form: Classify(name)}
	if q.form == FormUnicode {
		q.key, q.items = fillKey(nil, make([]item, 0, len(name)*maxKeyRunesPerRune), name)
	}
	return q
}

// Compare returns Equal(query, name).
func (q *Query) Compare(name []byte) Verdict {
	if len(q.name) == 0 || len(name) == 0 {
		return Unknown
	}
	if bytes.Equal(q.name, name) {
		return Same
	}
	if opaqueWithZ(q.name, name) || opaqueWithZ(name, q.name) {
		return Different
	}
	fn := Classify(name)
	switch {
	case q.form == FormUndecided || fn == FormUndecided:
		return Unknown
	case q.form == FormOpaque || fn == FormOpaque:
		return Different
	}
	if cap(q.items) < len(name)*maxKeyRunesPerRune {
		q.items = make([]item, 0, len(name)*maxKeyRunesPerRune)
	}
	q.tmp, q.items = fillKey(q.tmp[:0], q.items, name)
	if bytes.Equal(q.key, q.tmp) {
		return Same
	}
	return Different
}

// opaqueWithZ reports whether long is short plus one 'z' and short is an opaque name.
func opaqueWithZ(long, short []byte) bool {
	return len(long) == len(short)+1 && long[len(short)] == 'z' && bytes.HasPrefix(long, short) && Classify(short) == FormOpaque
}

// item is a rune of a key under construction with its canonical combining class.
type item struct {
	r rune
	c uint8
}

// appendFolded appends NFD(fold(NFD(r))) as items.
func appendFolded(dst []item, r rune) []item {
	var first, second [maxKeyRunesPerRune]rune
	for _, a := range appendCanon(first[:0], r) {
		f, ok := lookup(foldIndex, foldRunes, a)
		if !ok {
			dst = append(dst, item{a, ccc(a)})
			continue
		}
		for _, g := range f {
			for _, h := range appendCanon(second[:0], g) {
				dst = append(dst, item{h, ccc(h)})
			}
		}
	}
	return dst
}

// appendCanon appends the full canonical decomposition of r.
func appendCanon(dst []rune, r rune) []rune {
	if r >= hangulS && r < hangulS+hangulCount {
		return appendHangul(dst, r)
	}
	if d, ok := lookup(decompIndex, decompRunes, r); ok {
		return append(dst, d...)
	}
	return append(dst, r)
}

// lookup finds r in a sorted index by binary search.
func lookup(idx []mapEntry, data []rune, r rune) ([]rune, bool) {
	lo, hi := 0, len(idx)
	for lo < hi {
		m := int(uint(lo+hi) >> 1)
		switch e := idx[m]; {
		case e.r == r:
			return data[e.off : e.off+uint32(e.n)], true
		case e.r < r:
			lo = m + 1
		default:
			hi = m
		}
	}
	return nil, false
}

// ccc is the canonical combining class of r.
func ccc(r rune) uint8 {
	if r < 0x300 {
		return 0
	}
	lo, hi := 0, len(cccTable)
	for lo < hi {
		m := int(uint(lo+hi) >> 1)
		switch e := cccTable[m]; {
		case r < e.lo:
			hi = m
		case r > e.hi:
			lo = m + 1
		default:
			return e.class
		}
	}
	return 0
}

func isIgnorable(r rune) bool {
	lo, hi := 0, len(ignorableTable)
	for lo < hi {
		m := int(uint(lo+hi) >> 1)
		switch e := ignorableTable[m]; {
		case r < e.lo:
			hi = m
		case r > e.hi:
			lo = m + 1
		default:
			return true
		}
	}
	return false
}

// reorder puts every run of non-starters in canonical order (a stable insertion sort by class; a run is at
// most the length of the buffer, which is bounded by MaxName*maxKeyRunesPerRune).
func reorder(items []item) {
	for i := 1; i < len(items); i++ {
		if items[i].c == 0 {
			continue
		}
		for j := i; j > 0 && items[j-1].c > items[j].c; j-- {
			items[j-1], items[j] = items[j], items[j-1]
		}
	}
}
